// ============================================================
// CALCULER LE RYTHME DE CHAQUE CLIENT
// Pour chaque client, on regarde :
//   1. à quelle fréquence il commande d'habitude (son rythme)
//   2. depuis combien de jours il n'a rien commandé
// Le nœud suivant garde ceux qui ont "décroché".
// ============================================================

const reglages = $('Réglages').first().json;
const ventes = $("Lire l'historique des ventes").all().map(item => item.json);
const clients = $('Lire les clients').all().map(item => item.json);

const UN_JOUR = 24 * 60 * 60 * 1000;

// --- Outil : lire une date du tableur (2026-10-19, 19/10/2026 ou numéro de série)
function lireDate(valeur) {
  if (valeur === undefined || valeur === null || valeur === '') return null;
  if (typeof valeur === 'number') return new Date(Date.UTC(1899, 11, 30) + valeur * UN_JOUR);
  const texte = String(valeur).trim();
  let m = texte.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  m = texte.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return new Date(Date.UTC(+m[3], +m[2] - 1, +m[1]));
  return null;
}

// --- Outil : lire un nombre ("1 234,50 €" ou 1234.5)
function lireNombre(valeur) {
  if (typeof valeur === 'number') return valeur;
  const texte = String(valeur ?? '').replace(/[\s  €]/g, '').replace(',', '.');
  return parseFloat(texte) || 0;
}

const formatDate = d => d.toISOString().slice(0, 10).split('-').reverse().join('/');

// --- Date de référence : aujourd'hui (ou la date forcée dans Réglages)
const maintenant = $now.setZone('Europe/Paris');
const reference = lireDate(reglages.date_de_reference)
  ?? new Date(Date.UTC(maintenant.year, maintenant.month - 1, maintenant.day));

// 1. On regroupe les ventes par client : ses jours de commande et ses produits
const parClient = {};
for (const vente of ventes) {
  const date = lireDate(vente.date);
  if (!date || !vente.id_client || date > reference) continue;
  if (!parClient[vente.id_client]) parClient[vente.id_client] = { jours: new Set(), produits: {}, ca12mois: 0 };
  const c = parClient[vente.id_client];
  c.jours.add(date.getTime());
  c.produits[vente.produit] = (c.produits[vente.produit] || 0) + lireNombre(vente.quantite_cartons);
  if (reference - date <= 365 * UN_JOUR) c.ca12mois += lireNombre(vente.ca_ht);
}

// 2. Pour chaque client du fichier Clients : son rythme et sa dernière commande
const resultat = [];
for (const fiche of clients) {
  const c = parClient[fiche.id_client];
  if (!c || c.jours.size < 3) continue; // moins de 3 commandes : pas encore de rythme

  const jours = [...c.jours].sort((a, b) => a - b);
  const premiere = jours[0];
  const derniere = jours[jours.length - 1];

  // Rythme = écart moyen entre deux commandes
  const rythme = (derniere - premiere) / UN_JOUR / (jours.length - 1);
  const joursDepuis = Math.round((reference - derniere) / UN_JOUR);

  // Ses 3 produits les plus commandés
  const produitsHabituels = Object.entries(c.produits)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3)
    .map(([produit]) => produit);

  resultat.push({
    client: fiche.client,
    contact: fiche.contact,
    email: fiche.email,
    type: fiche.type,
    ville: fiche.ville,
    nb_commandes: jours.length,
    rythme_moyen_jours: Math.round(rythme),
    derniere_commande: formatDate(new Date(derniere)),
    jours_depuis_derniere_commande: joursDepuis,
    produits_habituels: produitsHabituels.join(', '),
    ca_12_derniers_mois: Math.round(c.ca12mois),
  });
}

// Les plus gros clients en premier
resultat.sort((a, b) => b.ca_12_derniers_mois - a.ca_12_derniers_mois);
return resultat.map(json => ({ json }));

